(function(){'use strict';
const M=AvalonMath,$=id=>document.getElementById(id),bridge=window.DesktopApp?.avalon,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const panel=document.createElement('section');panel.id='avalon-content';panel.className='activity-content';panel.hidden=true;
panel.innerHTML=`<section class="panel avalon-heading"><div><h2>Avalon Checker</h2><p>Карты, ресурсы и заметки о дорогах Авалона</p></div><div class="avalon-actions"><button id="avalon-scan" class="button">Считать через 3 секунды</button><button id="avalon-import" class="button">Подключить папку Checker</button></div><p id="avalon-status" class="hint" role="status"></p><label class="avalon-hotkey"><input id="avalon-hotkey" type="checkbox"> Горячая клавиша Ctrl+Shift+A</label><p class="hint">Наведите курсор на название портала, затем нажмите горячую клавишу. Карта появится поверх игры. Снимок распознаётся локально.</p></section>
<div class="avalon-layout"><section class="panel avalon-browser"><label class="field">Найти зону<input id="avalon-query" type="search" placeholder="Название или часть названия…" maxlength="100"></label><div class="grid2"><label class="field">Мир<select id="avalon-world"><option value="roads">Весь Авалон</option><option value="all">Все зоны</option>${Object.entries(M.worlds).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label><label class="field">Тир<select id="avalon-tier"><option value="">Любой</option>${[1,2,3,4,5,6,7,8].map(n=>`<option>${n}</option>`).join('')}</select></label><label class="field">Ресурс<select id="avalon-resource"><option value="">Любой</option>${Object.entries(M.resources).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label><label class="field">Сундуки<select id="avalon-chest"><option value="">Любые</option>${Object.entries(M.chests).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label></div><label><input id="avalon-only-favorites" type="checkbox"> Только избранное</label><p id="avalon-count" class="hint"></p><div id="avalon-results" class="avalon-results" aria-label="Найденные зоны"></div><div class="avalon-pages"><button id="avalon-prev" class="button">←</button><span id="avalon-page"></span><button id="avalon-next" class="button">→</button></div></section>
<section class="panel avalon-detail"><div class="avalon-zone-heading"><div><h2 id="avalon-zone-name">Подключите Avalon Checker</h2><p id="avalon-zone-meta" class="hint">Используется локальная папка скачанной программы.</p></div><button id="avalon-favorite" class="button" disabled aria-label="Добавить зону в избранное">☆</button></div><div class="avalon-actions"><button id="avalon-map-open" class="button" disabled>Карта крупнее</button><button id="avalon-overlay" class="button" disabled>Поверх игры</button><button id="avalon-copy" class="button" disabled>Копировать название</button></div><div id="avalon-map" class="avalon-map"><p class="hint">Карты будут скопированы в профиль Albion Lab и останутся доступны без интернета.</p></div><div id="avalon-features" class="avalon-features"></div><p id="avalon-map-note" class="hint"></p><label class="field">Моя заметка<textarea id="avalon-note" rows="3" maxlength="2000" disabled></textarea></label><button id="avalon-note-save" class="button" disabled>Сохранить заметку</button></section></div>
<section class="panel"><h2>Мои порталы</h2><p class="hint">Запишите уже найденное соединение и время до закрытия из игры. Список разделён по серверам; срок не подтверждает, что проход всё ещё открыт.</p><div class="avalon-timer-form"><label class="field">Из зоны<select id="avalon-from"></select></label><label class="field">В зону<input id="avalon-to" list="avalon-zone-list" maxlength="100" placeholder="Название зоны"></label><datalist id="avalon-zone-list"></datalist><label class="field">До закрытия, минут<input id="avalon-minutes" type="number" min="1" max="1440" step="1" value="60"></label><button id="avalon-timer-add" class="button">Добавить портал</button></div><div id="avalon-timers"></div></section>`;
document.querySelector('main>footer').before(panel);
let active=false,loaded=false,zones=[],selected='',page=0,zoom=1,store,error='',tick,hotkeyEnabled=false;
try{store=M.storage(localStorage);}catch(e){error=e.message;}
function message(s,bad=false){$('avalon-status').textContent=s;$('avalon-status').classList.toggle('avalon-error',bad);}
const saved=()=>store?.snapshot()||{favorites:[],notes:{},timers:[]};
function filters(){return {query:$('avalon-query').value,world:$('avalon-world').value,tier:$('avalon-tier').value,resource:$('avalon-resource').value,chest:$('avalon-chest').value,favorites:$('avalon-only-favorites').checked?saved().favorites:null};}
function results(){const rows=M.search(zones,filters()),pages=Math.max(1,Math.ceil(rows.length/30));page=Math.max(0,Math.min(page,pages-1));$('avalon-count').textContent=`Найдено ${rows.length} · в справочнике ${zones.length}`;$('avalon-results').innerHTML=rows.slice(page*30,page*30+30).map(z=>`<button class="avalon-result ${z.id===selected?'selected':''}" data-avalon-zone="${esc(z.id)}"><b>${esc(z.name)}</b><span>T${z.tier} · ${esc(M.worlds[z.world])}${saved().favorites.includes(z.id)?' · ★':''}</span></button>`).join('')||'<p class="hint">Ничего не найдено. Измените название или фильтры.</p>';$('avalon-page').textContent=`${page+1} / ${pages}`;$('avalon-prev').disabled=page===0;$('avalon-next').disabled=page>=pages-1;}
function features(z){return M.featureGroups(z).map(g=>`<div><h3>${esc(g.title)}</h3>${g.items.map(item=>`<span class="avalon-chip">${esc(item)}</span>`).join('')||'<p class="hint">В справочнике не указаны</p>'}</div>`).join('');}
function select(id){const z=zones.find(z=>z.id===id);if(!z)return;selected=id;zoom=1;$('avalon-zone-name').textContent=z.name;$('avalon-zone-meta').textContent=`T${M.zoneLabel(z)} · ${M.worlds[z.world]} · ${z.id}`;$('avalon-favorite').textContent=saved().favorites.includes(id)?'★':'☆';$('avalon-favorite').disabled=!store;$('avalon-favorite').setAttribute('aria-pressed',String(saved().favorites.includes(id)));$('avalon-note').value=saved().notes[id]||'';$('avalon-note').disabled=!store;$('avalon-note-save').disabled=!store;$('avalon-copy').disabled=false;$('avalon-map-open').disabled=!z.image;$('avalon-overlay').disabled=!bridge;$('avalon-map').innerHTML=z.image?`<img src="avalon-local/${encodeURIComponent(z.image)}" alt="Карта ${esc(z.name)}">`:'<p class="hint">Изображение этой зоны отсутствует в локальном справочнике.</p>';$('avalon-features').innerHTML=features(z);$('avalon-map-note').textContent='Показаны сведения локального справочника. Текущие соединения, наличие и состояние сундуков не проверяются.';$('avalon-from').value=id;results();}
function timers(){const rows=saved().timers.filter(t=>t.server===api.state.server);$('avalon-timers').innerHTML=rows.map(t=>{const seconds=Math.ceil((t.expires-Date.now())/1000),name=id=>zones.find(z=>z.id===id)?.name||id;return `<div class="avalon-timer"><span>${esc(name(t.from))} ↔ ${esc(name(t.to))}</span><b class="${seconds<=0?'avalon-error':''}">${seconds<=0?'Время истекло':Math.floor(seconds/3600)+' ч '+Math.floor(seconds%3600/60)+' мин'}</b><button class="button" data-avalon-delete="${esc(t.id)}" aria-label="Удалить портал">Удалить</button></div>`;}).join('')||'<p class="hint">Для текущего сервера порталов пока нет.</p>';}
async function load(force=false){if(loaded&&!force)return;loaded=true;if(bridge)bridge.hotkey().then(s=>{hotkeyEnabled=s.enabled;$('avalon-hotkey').checked=hotkeyEnabled;}).catch(()=>{});if(!bridge){message('Подключение локального Checker доступно в настольном приложении.',true);return;}try{const result=await bridge.library();zones=result.zones||[];if(!result.ready){message(result.error||'Не удалось найти папку Checker автоматически. Нажмите «Подключить папку Checker».',!!result.error);return;}message(`Подключено: ${zones.length} зон, ${result.maps} карт. Работает без интернета.`);$('avalon-scan').disabled=false;$('avalon-hotkey').disabled=false;$('avalon-from').innerHTML=zones.map(z=>`<option value="${esc(z.id)}">${esc(z.name)}</option>`).join('');$('avalon-zone-list').innerHTML=zones.map(z=>`<option value="${esc(z.name)}"></option>`).join('');select(zones.some(z=>z.id===selected)?selected:zones.find(z=>z.world==='avalon')?.id||zones[0]?.id);results();timers();}catch(e){message(e.message,true);}}
const api={panel,state:{server:'europe'},active:()=>active,activate(){active=true;document.getElementById('craft-content').hidden=true;panel.hidden=false;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode==='avalon'));$('refresh').hidden=true;$('title').textContent='Avalon Checker';$('subtitle').textContent='Карты и ресурсы дорог Авалона';load();api.render();clearInterval(tick);tick=setInterval(timers,15000);},deactivate(){active=false;panel.hidden=true;$('refresh').hidden=false;clearInterval(tick);},setServer(server){api.state.server=server;},render(){results();timers();$('avalon-hotkey').checked=hotkeyEnabled;if(error)message(error,true);},refresh(){return load();},captureDraft:()=>({selected}),restoreDraft(draft){if(draft?.selected&&zones.some(z=>z.id===draft.selected))select(draft.selected);else if(draft?.selected)selected=draft.selected;}};
ActivityViews.avalon=api;
$('avalon-results').onclick=e=>{const b=e.target.closest('[data-avalon-zone]');if(b)select(b.dataset.avalonZone);};
for(const id of ['avalon-query','avalon-world','avalon-tier','avalon-resource','avalon-chest','avalon-only-favorites'])$(id).addEventListener(id==='avalon-query'?'input':'change',()=>{page=0;results();});
$('avalon-prev').onclick=()=>{page--;results();};$('avalon-next').onclick=()=>{page++;results();};
$('avalon-import').onclick=async()=>{try{$('avalon-import').disabled=true;const result=await bridge?.importFolder();if(result&&!result.cancelled)await load(true);}catch(e){message(e.message,true);}finally{$('avalon-import').disabled=false;}};
$('avalon-favorite').onclick=()=>{try{store.favorite(selected);$('avalon-favorite').textContent=saved().favorites.includes(selected)?'★':'☆';$('avalon-favorite').setAttribute('aria-pressed',String(saved().favorites.includes(selected)));results();}catch(e){message(e.message,true);}};
$('avalon-note-save').onclick=()=>{try{store.note(selected,$('avalon-note').value);message('Заметка сохранена.');}catch(e){message(e.message,true);}};
$('avalon-copy').onclick=async()=>{try{await navigator.clipboard.writeText(zones.find(z=>z.id===selected).name);message('Название скопировано.');}catch{message('Не удалось скопировать название.',true);}};
$('avalon-timer-add').onclick=()=>{try{const to=zones.find(z=>M.normalize(z.name)===M.normalize($('avalon-to').value));if(!to)throw Error('Выберите точное название зоны из подсказок.');store.timer({server:api.state.server,from:$('avalon-from').value,to:to.id,minutes:Number($('avalon-minutes').value)});timers();message('Портал добавлен.');}catch(e){message(e.message,true);}};
$('avalon-timers').onclick=e=>{const b=e.target.closest('[data-avalon-delete]');if(b)try{store.remove(b.dataset.avalonDelete);timers();}catch(e){message(e.message,true);}};
const dialog=document.createElement('dialog');dialog.className='avalon-map-dialog';dialog.innerHTML='<div class="avalon-actions"><button id="avalon-map-close" class="button">Закрыть</button><button id="avalon-map-minus" class="button">−</button><button id="avalon-map-plus" class="button">+</button><span id="avalon-map-scale">100%</span></div><div class="avalon-map-large"></div>';document.body.append(dialog);
$('avalon-map-open').onclick=()=>{dialog.querySelector('.avalon-map-large').innerHTML=$('avalon-map').innerHTML;zoom=1;$('avalon-map-scale').textContent='100%';dialog.showModal();};$('avalon-map-close').onclick=()=>dialog.close();for(const [id,delta]of [['avalon-map-minus',-.25],['avalon-map-plus',.25]])$(id).onclick=()=>{zoom=Math.min(3,Math.max(.5,zoom+delta));dialog.querySelector('img').style.width=100*zoom+'%';$('avalon-map-scale').textContent=Math.round(zoom*100)+'%';};
$('avalon-overlay').onclick=async()=>{try{await bridge?.overlay(selected);}catch(e){message(e.message,true);}};
async function scanned(result){if(!loaded)await load();if(result.error){message(result.error,true);return;}const matches=M.recognize(zones,result.text);if(!active)CraftApp.navigate('avalon');if(!matches.length){message('Название не распознано. Наведите курсор на название портала или введите его вручную.',true);return;}const best=matches[0];$('avalon-world').value='all';$('avalon-query').value=best.zone.name;$('avalon-tier').value=$('avalon-resource').value=$('avalon-chest').value='';$('avalon-only-favorites').checked=false;page=0;select(best.zone.id);message(`Распознано: ${best.zone.name} · совпадение ${best.score}%. Проверьте название перед переходом.`);}
$('avalon-scan').disabled=true;$('avalon-hotkey').disabled=true;
$('avalon-scan').onclick=async()=>{try{$('avalon-scan').disabled=true;message('Через 3 секунды: переключитесь в игру и наведите курсор на название портала…');await new Promise(r=>setTimeout(r,3000));await scanned(await bridge.scan());}catch(e){message(e.message,true);}finally{$('avalon-scan').disabled=!bridge||!zones.length;}};
$('avalon-hotkey').onchange=async()=>{try{const state=await bridge.hotkey($('avalon-hotkey').checked);hotkeyEnabled=state.enabled;$('avalon-hotkey').checked=state.enabled;message(state.enabled?'Ctrl+Shift+A включена. Наведите курсор на название портала в игре.':'Горячая клавиша выключена.');}catch(e){$('avalon-hotkey').checked=false;message(e.message,true);}};
bridge?.onScan(scanned);window.AvalonUI={...api,select,load,features,catalog:()=>zones,removeTimer(id){store.remove(id);timers();},removeConnection(server,from,to){store.removePair(server,from,to);timers();},snapshot:()=>({selected,zones:zones.length,filters:filters(),saved:saved()})};
})();
